// ================= THEME: the only place you need to edit to change how the puck looks =================
// Soft pink, simple and cute. Change a colour below and rebuild; every page follows.
// Colours are 0xRRGGBB. The cute shapes (hearts, bows, flowers, bunny ears) are in art.h
// (generated by tools/gen_art.py as masks, so they take the colours from here).
#pragma once
#include "art.h"

// ---- colours ----
#define C_BG      0xFFF0F5   // page background (very light pink)
#define C_SURF    0xFFE4EC   // pink surface (spinner track, bars)
#define C_CARD    0xFFFBF7   // cream card / button fill
#define C_TEXT    0x6D4C5B   // main text: soft brown-mauve (instead of black)
#define C_GREY    0xA98A97   // secondary text
#define C_DIV     0xF8CCDB   // thin dividers
#define C_LINE    0xF4B6CB   // outlines and the dotted ring
#define C_PRESS   0xFFD3E2   // pressed button
#define C_ACCENT  0xF48FB1   // rose pink: sliders, bars, hearts
#define C_HOT     0xEC407A   // hot pink: record button, bow knot, selected dot
#define C_RED     C_HOT      // "record / stop / error" colour (kept pink on purpose)
#define C_BUTTER  0xFFE082   // flower centres
#define C_RED_TXT "#EC407A"  // same as C_HOT, as text for coloured labels

// ---- shape ----
#define T_RADIUS      18     // buttons and cards
#define T_RADIUS_PILL 22     // pill buttons (height / 2 or more)
#define T_RING_DOTS   64     // dots in the dotted border ring
#define T_RING_R      169    // ring radius from the screen centre (screen is 360 wide)

// ---- fonts (Montserrat is built in and clean; a rounded font would need extra flash) ----
#define T_FONT_S   (&lv_font_montserrat_12)
#define T_FONT_M   (&lv_font_montserrat_14)
#define T_FONT_L   (&lv_font_montserrat_16)
#define T_FONT_XL  (&lv_font_montserrat_20)
#define T_FONT_XXL (&lv_font_montserrat_48)

// ---- little drawing helpers ----
// Put one of the art.h shapes on a parent, tinted with a theme colour.
static lv_obj_t *theme_art(lv_obj_t *p, const lv_img_dsc_t *img, uint32_t col, lv_align_t al, int x, int y) {
  lv_obj_t *o = lv_img_create(p); lv_img_set_src(o, img);
  lv_obj_set_style_img_recolor(o, lv_color_hex(col), 0); lv_obj_set_style_img_recolor_opa(o, LV_OPA_COVER, 0);
  lv_obj_clear_flag(o, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_align(o, al, x, y);
  return o;
}
static void theme_heart(lv_obj_t *p, int x, int y, bool small_ = false) {
  theme_art(p, small_ ? &art_heart_s : &art_heart, C_ACCENT, LV_ALIGN_TOP_MID, x, y);
}
static void theme_bow(lv_obj_t *p, lv_align_t al, int x, int y) {   // a little bow: two loops and a knot
  theme_art(p, &art_bow, C_ACCENT, al, x, y);
  theme_art(p, &art_bow_knot, C_HOT, al, x, y);
}
static void theme_flower(lv_obj_t *p, lv_align_t al, int x, int y, bool small_ = false) {
  theme_art(p, small_ ? &art_flower_s : &art_flower, C_ACCENT, al, x, y);
  if (!small_) theme_art(p, &art_flower_core, C_BUTTER, al, x, y);
}
static void theme_bunny_ears(lv_obj_t *p, int y) {   // original bunny-ear motif
  theme_art(p, &art_ears, C_ACCENT, LV_ALIGN_TOP_MID, 0, y);
  theme_art(p, &art_ears_in, C_SURF, LV_ALIGN_TOP_MID, 0, y);
}
// Dotted border ring around the round screen. Lives on the top layer so every page shows it.
static void theme_ring() {
  for (int i = 0; i < T_RING_DOTS; i++) {
    float a = i * 6.2831853f / T_RING_DOTS;
    lv_obj_t *d = lv_obj_create(lv_layer_top()); lv_obj_remove_style_all(d);
    lv_obj_set_size(d, 4, 4); lv_obj_set_style_radius(d, LV_RADIUS_CIRCLE, 0);
    lv_obj_set_style_bg_opa(d, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(d, lv_color_hex(i % 4 == 0 ? C_ACCENT : C_LINE), 0);
    lv_obj_clear_flag(d, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_set_pos(d, 178 + (int)(T_RING_R * cosf(a)), 178 + (int)(T_RING_R * sinf(a)));
  }
}
// Pink progress/level bar and slider look (used by recorder, settings, playback)
static void theme_bar(lv_obj_t *b, int h) {
  lv_obj_set_height(b, h);
  lv_obj_set_style_radius(b, LV_RADIUS_CIRCLE, LV_PART_MAIN); lv_obj_set_style_radius(b, LV_RADIUS_CIRCLE, LV_PART_INDICATOR);
  lv_obj_set_style_bg_color(b, lv_color_hex(C_SURF), LV_PART_MAIN); lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_bg_color(b, lv_color_hex(C_ACCENT), LV_PART_INDICATOR); lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_PART_INDICATOR);
}
